l,"construction_century":null},{"id":"4db78e70-c6ce-4c19-a4b5-93dc8f519b9b","name":"Oachira Temple","deity":"Parabrahma","sampradaya":null,"significance":[],"country":"India","state":"Kerala","district":"Kollam","town":"Oachira","latitude":9.136,"longitude":76.5102,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Karippuzha Thodu River","river_distance_km":3.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T10:59:23.880063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An ancient pilgrimage centre at Oachira on the Kollam-Alappuzha border in Kerala, focused on the Parabrahma shrine and spread over thirty-six acres. It is called Dakshina Kashi. Notable events include the Vrischikam festival in December-January, the mock-fighting Oachirakali in June, and a cattle festival with large bull effigies.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Thiruvananthapuram International Airport","nearest_airport_distance_km":85.5,"nearest_railway_station_name":"Ochira railway station","nearest_railway_distance_km":1.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Oachira Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"4dee78b7-3f46-42be-b70d-b2212182757b","name":"Kashi Vishwanath Temple","deity":"Shiva (Kashi Vishwanath)","sampradaya":"Smartha","significance":["Jyotirlinga","Sapta Puri"],"country":"India","state":"Uttar Pradesh","district":"Varanasi","town":"Varanasi","latitude":25.3109,"longitude":83.0107,"sandhya_friendly":"yes","sandhya_notes":"Ghat steps a short walk away provide open river access for Sandhya Vandanam at sunrise and sunset.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Kashi Annapurna Bhavan (pure veg mess near Vishwanath Gali)","food_source_contact":"+91-98765-43210","food_distance_km":0.3,"nearest_river_name":"Ganga","river_distance_km":0.2,"best_season_notes":"Oct–Nov and Feb–Mar avoid both the summer heat (Apr–Jun) and the thick winter fog that can disrupt road and rail travel across the Gangetic plain in Dec–Jan; the ghats are pleasant and the queue is shorter on weekday mornings either way.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-04T08:49:12.455773+00:00","sthala_purana":"Kashi is described as resting on Shiva's trident, standing apart from the earth and untouched by the dissolution of the worlds. The sthala purana relates that Shiva made this his eternal abode, and that those who die here receive the taraka mantra from him at the moment of death.","etiquette_notes":"Leather items (belts, wallets, bags) and phones/cameras are not permitted near the sanctum — free cloakrooms are available outside. Expect an airport-style security check on the approach to the main shrine, especially on Mondays and during Shravan.","native_name":"काशी विश्वनाथ मन्दिर","morning_opens_at":"03:00:00","morning_closes_at":"12:00:00","evening_opens_at":"16:00:00","evening_closes_at":"21:00:00","timings_notes":"The Mangala Aarti before dawn is a well-known separate ticketed slot.","accessibility_notes":null,"nearest_airport_name":"Varanasi (Lal Bahadur Shastri) Airport","nearest_airport_distance_km":25,"nearest_railway_station_name":"Varanasi Junction","nearest_railway_distance_km":5,"emergency_contact_notes":null,"sthala_purana_source":"Shiva Purana / Skanda Purana (Jyotirlinga tradition)","architecture_style":"Nagara","constructio