mmarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"5404cda9-dec9-4fcd-8271-a8393c6f6099","name":"Tukreswari Temple","deity":"Sati (Tukreswari)","sampradaya":"Shakta","significance":[],"country":"India","state":"Assam","district":"Goalpara","town":"Krishnai","latitude":26.04956,"longitude":90.63219,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Krishnai River","river_distance_km":4.1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:54.58588+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An ancient temple in Goalpara district, Assam, regarded as a Shakta pitha. According to tradition, a fragment of Sati's body fell here, and the name comes from the Assamese word tukura, meaning piece.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Rupsi Airport","nearest_airport_distance_km":73.1,"nearest_railway_station_name":"Krishnai railway station","nearest_railway_distance_km":5.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Tukreswari Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"5437478b-8e29-4ccb-af02-9f9d0b63dd96","name":"Bipattarini Chandibari, Rajpur","deity":"Bipadtarini, an aspect of Durga","sampradaya":"Shakta","significance":[],"country":"India","state":"West Bengal","district":"South 24 Parganas","town":"Rajpur Sonarpur","latitude":22.42688,"longitude":88.41224,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier