name":"Chennai International Airport","nearest_airport_distance_km":9.5,"nearest_railway_station_name":"Kodambakkam railway station","nearest_railway_distance_km":0.5,"emergency_contact_notes":null,"sthala_purana_source":"Contributor-submitted local survey","architecture_style":null,"construction_century":null},{"id":"60310ca8-e0ac-4459-a1b7-9171229f4420","name":"Kumari Amman Temple, Kanyakumari","deity":"Kanyakumari / Bhagavathy Amman (virgin form of Devi)","sampradaya":"Shakta","significance":["Ashta Dasa Shakti Peetha"],"country":"India","state":"Tamil Nadu","district":"Kanyakumari","town":"Kanyakumari","latitude":8.0788,"longitude":77.5385,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pazhayar River","river_distance_km":5.9,"best_season_notes":"Oct–Mar.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-08T06:23:03.123234+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Standing at India's southernmost tip, where tradition holds the Bay of Bengal, the Arabian Sea, and the Indian Ocean meet, this ancient shrine is dedicated to Devi in her eternal-virgin form. Tradition holds she undertook penance to marry Shiva so as to gain the boon needed to slay the demon Bana, but the sage Narada, knowing only a virgin goddess could defeat him, contrived to delay the wedding past its auspicious hour — leaving the uneaten wedding rice and grain scattered on the shore, said to be the source of the multi-coloured sand found on Kanyakumari's beaches to this day. The site was known to ancient Mediterranean geographers, who recorded it as \"Comorin\".","etiquette_notes":null,"native_name":"குமரி அம்மன் கோயில்","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":nul